/**
 * Built-in sample decks: original notes written for this project, with questions pre-generated by the real
 * pipeline and reviewed by hand at build time (see scripts/build-samples.ts). Shipped as static JSON, so they
 * work offline and without the AI service. Loaded lazily.
 */
import { z } from 'zod';
import { QuestionContentSchema } from '../../shared/question';
import { db } from '../db/schema';
import { createDeck, updateDeck } from '../db/repo';
import { newId } from './learning/random';
import { SKILL_START } from './learning/mastery';
import { chunkKey } from './deck/ids';
import { startBackgroundGeneration } from './deck/generate';

export const SampleSchema = z.object({
  id: z.string(),
  title: z.string(),
  language: z.string(),
  description: z.string(),
  source: z.string(),
  chunks: z.array(
    z.object({
      text: z.string(),
      headingPath: z.array(z.string()),
      page: z.number().int().optional(),
      wordCount: z.number().int(),
    }),
  ),
  topics: z.array(
    z.object({ key: z.string(), title: z.string(), summary: z.string(), chunks: z.array(z.number().int()) }),
  ),
  questions: z.array(z.object({ topic: z.string(), content: QuestionContentSchema })),
});
export type SampleDeck = z.infer<typeof SampleSchema>;

export interface SampleInfo {
  id: string;
  title: string;
  language: string;
  description: string;
  questions: number;
  load: () => Promise<SampleDeck>;
}

const modules = import.meta.glob<{ default: unknown }>('../samples/*.json');
const meta = import.meta.glob<{ default: Array<Omit<SampleInfo, 'load'>> }>('../samples/index.ts', {
  eager: true,
});

export function listSamples(): SampleInfo[] {
  const index = Object.values(meta)[0]?.default ?? [];
  return index
    .map((m) => {
      const load = modules[`../samples/${m.id}.json`];
      return load ? { ...m, load: async () => SampleSchema.parse((await load()).default) } : null;
    })
    .filter((x): x is SampleInfo => !!x);
}

/** Opens a sample deck: imports it into the local database the first time, otherwise returns the existing deck. */
export async function openSample(info: SampleInfo): Promise<string> {
  const existing = await db.decks.filter((d) => d.sampleId === info.id).first();
  if (existing) return existing.id;
  const s = await info.load();
  const deck = await createDeck({
    title: s.title,
    quizLanguage: s.language,
    examDate: null,
    sampleId: s.id,
    notesLanguage: s.language,
  });
  const sourceId = newId();
  await db.transaction('rw', [db.sources, db.chunks, db.topics, db.questions], async () => {
    await db.sources.add({
      id: sourceId,
      deckId: deck.id,
      name: s.source,
      kind: 'markdown',
      units: 1,
      bytes: 0,
      addedAt: Date.now(),
    });
    await db.chunks.bulkAdd(
      s.chunks.map((c, i) => ({
        id: chunkKey(deck.id, i),
        deckId: deck.id,
        index: i,
        text: c.text,
        headingPath: c.headingPath,
        refs: [{ sourceId, headingPath: c.headingPath, ...(c.page ? { page: c.page } : {}) }],
        wordCount: c.wordCount,
      })),
    );
    await db.topics.bulkAdd(
      s.topics.map((t, i) => ({
        id: `${deck.id}:${t.key}`,
        deckId: deck.id,
        key: t.key,
        order: i,
        title: t.title,
        summary: t.summary,
        chunkIds: t.chunks.map((c) => chunkKey(deck.id, c)),
        skill: SKILL_START,
        status: 'ready' as const,
        emptyRounds: 0,
      })),
    );
    await db.questions.bulkAdd(
      s.questions.map((q) => ({
        id: newId(),
        deckId: deck.id,
        topicId: `${deck.id}:${q.topic}`,
        content: {
          ...q.content,
          topicId: `${deck.id}:${q.topic}`,
          sourceChunkIds: q.content.sourceChunkIds.map((c) => `${deck.id}:${c}`),
        },
        createdAt: Date.now(),
        reported: null,
      })),
    );
  });
  await updateDeck(deck.id, { status: 'ready', stage: 'done' });
  // Sample decks already have plenty of questions; more are only generated on demand when online.
  if (navigator.onLine) startBackgroundGeneration(deck.id);
  return deck.id;
}
